-- ============================================================================
-- NEXUS MATRIX AGENTS CLUSTER — DDL + catálogo completo dos agentes especialistas
-- Migração: supabase_matrix_agents_cluster.sql · 2026-09-07 · Etapa 21
-- ----------------------------------------------------------------------------
-- Arquitetura: Matrix Agent Cluster — 1 Edge Function orquestradora +
-- catálogo em banco (nexus_agents) + fila agendada (nexus_agent_tasks_queue).
-- NÃO instancia processo por agente: agentes são LINHAS, não containers —
-- custo de Vercel/repo inalterado, escala horizontal via banco.
--
-- PROPRIEDADES (alinhadas ao growth_hacker_engine v2.1):
--   · fail-closed  · idempotente (re-executável) · DDL apenas aditiva
--   · zero segredos hardcoded · telemetria via nexus_cron_telemetry_log()
--   · READ-ONLY sobre ads (14.036), nexus_ecommerce_routes, nexus_social_outbox,
--     ads_seo_submissions — o cluster NUNCA escreve nas tabelas de produção.
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. CATÁLOGO DE AGENTES
-- ---------------------------------------------------------------------------
create table if not exists public.nexus_agents (
  id                 uuid primary key default gen_random_uuid(),
  agent_slug         text not null unique
                       check (agent_slug = lower(agent_slug) and agent_slug <> ''),
  group_package      text not null,
  system_instruction text not null default '',
  active             boolean not null default true,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

comment on table public.nexus_agents is
  'Matrix Agent Cluster: catálogo dos agentes especialistas (1 linha = 1 agente).';

create index if not exists idx_nexus_agents_active_pkg
  on public.nexus_agents (active, group_package);

-- ---------------------------------------------------------------------------
-- 2. CATÁLOGO COMPLETO — inserção em lote (idempotente por agent_slug)
--    Pacotes estruturais factuais: engineering-it · marketing-productivity ·
--    finance-operations-legal (módulos: Eng, Mkt, Fin, Legal, Ops, Prod, Rec, Sales)
-- ---------------------------------------------------------------------------
on conflict (agent_slug) do nothing;

-- ---------------------------------------------------------------------------
-- 3. FILA DE EXECUÇÕES (agendamento das submissões e tráfego)
-- ---------------------------------------------------------------------------
create table if not exists public.nexus_agent_tasks_queue (
  id           bigint generated always as identity primary key,
  agent_slug   text not null
                 references public.nexus_agents(agent_slug) on delete cascade,
  status       text not null default 'pending'
                 check (status in ('pending','running','done','failed','skipped')),
  priority     integer not null default 100 check (priority between 0 and 1000),
  payload      jsonb not null default '{}'::jsonb,
  result       jsonb,
  error        text,
  attempts     integer not null default 0,
  max_attempts integer not null default 2 check (max_attempts between 1 and 5),
  run_after    timestamptz not null default now(),
  claimed_at   timestamptz,
  finished_at  timestamptz,
  created_at   timestamptz not null default now()
);

create index if not exists idx_nexus_tasks_queue_poll
  on public.nexus_agent_tasks_queue (status, run_after, priority);

comment on table public.nexus_agent_tasks_queue is
  'Fila do Matrix Agent Cluster: execuções agendadas, com backoff e reentrega.';

-- ---------------------------------------------------------------------------
-- 4. API DE FILA — enqueue / claim (SKIP LOCKED) / complete / fail
--    Somente service_role (edge function orquestradora). Fail-closed.
-- ---------------------------------------------------------------------------
create or replace function public.nexus_matrix_enqueue(
  p_agent_slug text, p_payload jsonb default '{}'::jsonb, p_priority integer default 100)
returns bigint language plpgsql security invoker set search_path = public as $fn$
declare v_id bigint;
begin
  if not exists (select 1 from public.nexus_agents a
                 where a.agent_slug = p_agent_slug and a.active) then
    raise exception 'agente inativo ou inexistente: %', p_agent_slug;
  end if;
    values (p_agent_slug, coalesce(p_payload,'{}'::jsonb), coalesce(p_priority,100))
  returning id into v_id;
  return v_id;
end $fn$;

create or replace function public.nexus_matrix_claim_tasks(
  p_limit integer default 8, p_stale_seconds integer default 1800)
returns setof public.nexus_agent_tasks_queue
language plpgsql security invoker set search_path = public as $fn$
begin
  -- recupera tarefas 'running' órfãs (crash/timeout) — fail-closed com reentrega
  update public.nexus_agent_tasks_queue q
     set status = 'pending', claimed_at = null
   where q.status = 'running'
     and q.claimed_at < now() - (coalesce(p_stale_seconds,1800) || ' seconds')::interval;

  return query
  update public.nexus_agent_tasks_queue q
     set status = 'running', claimed_at = now(), attempts = q.attempts + 1
   where q.id in (
     select id from public.nexus_agent_tasks_queue
      where status = 'pending' and run_after <= now()
      order by priority asc, run_after asc
      limit greatest(coalesce(p_limit,8),0)
      for update skip locked)
  returning q.*;
end $fn$;

create or replace function public.nexus_matrix_complete_task(
  p_id bigint, p_result jsonb default null)
returns void language sql security invoker set search_path = public as $fn$
  update public.nexus_agent_tasks_queue
     set status = 'done', result = p_result, error = null, finished_at = now()
   where id = p_id and status = 'running';
$fn$;

create or replace function public.nexus_matrix_fail_task(
  p_id bigint, p_error text default null)
returns void language plpgsql security invoker set search_path = public as $fn$
begin
  update public.nexus_agent_tasks_queue
     set status = case when attempts >= max_attempts then 'failed' else 'pending' end,
         run_after = now() + (power(2, attempts) * 300 || ' seconds')::interval,
         error = left(coalesce(p_error,'erro não especificada'), 500),
         finished_at = case when attempts >= max_attempts then now() else finished_at end
   where id = p_id and status = 'running';
end $fn$;

revoke execute on function public.nexus_matrix_enqueue(text,jsonb,integer) from public;
revoke execute on function public.nexus_matrix_claim_tasks(integer,integer) from public;
revoke execute on function public.nexus_matrix_complete_task(bigint,jsonb) from public;
revoke execute on function public.nexus_matrix_fail_task(bigint,text) from public;
revoke all on public.nexus_agents from anon, authenticated;
revoke all on public.nexus_agent_tasks_queue from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 5. SEED — 3 tarefas farol para o primeiro ciclo do orquestrador
--    (sem chaves IA no vault: fail-closed → telemetria + backoff → 'failed')
-- ---------------------------------------------------------------------------
select s.slug, s.payload, s.prio
  from (values
    ('seo-audit',        '{"hosts":["aquitemachadinhos.com.br","solvegrid.com.br"]}'::jsonb, 10),
    ('traffic-analysis', '{"window_days":7,"source":"gsc"}'::jsonb, 20),
    ('weekly-ship-recap','{"window_days":7,"source":"github"}'::jsonb, 30)
  ) as s(slug, payload, prio)
 where not exists (select 1 from public.nexus_agent_tasks_queue t where t.agent_slug = s.slug);

-- ---------------------------------------------------------------------------
-- 6. VERIFICAÇÃO PÓS-APLICAÇÃO (executa e falha se o catálogo estiver menor)
-- ---------------------------------------------------------------------------
do $do$
declare n integer;
begin
  select count(*) into n from public.nexus_agents;
  if n < 216 then
    raise exception 'catálogo incompleto: % agentes (esperado >= 216)', n;
  end if;
  raise notice 'MATRIX AGENTS: % agentes ativos, % pacotes', n,
    (select count(distinct group_package) from public.nexus_agents);
end $do$;

commit;
